# intended-flows.yaml: the design, written as testable claims
zones:
  user:  { cidr: 10.10.0.0/16 }
  app:   { cidr: 10.20.0.0/24 }
  db:    { cidr: 10.30.0.0/24 }
tests:
  - { id: F1, from: user, to: db,  port: 5432, expect: blocked }
  - { id: F2, from: app,  to: db,  port: 5432, expect: open }
  - { id: F3, from: user, to: app, port: 443,  expect: open }
  - { id: F4, from: user, to: db,  port: 22,   expect: blocked }

